insert into public.stimuli (id, kind, body) values
  ('4d767ab6-78bf-ed52-47ce-79b6647ab6f1', 'reading', '{"title":"Optimalisasi Efisiensi Pewarna Alami UMKM Batik Yogya","subtitle":"Studi Kasus Efisiensi Sumber Daya Produksi dan Kapasitas Harian","source":"Kajian Efisiensi Sentra Kerajinan Tradisional DIY (2026)","text":"Sentra kerajinan batik cap ramah lingkungan di Imogiri, Yogyakarta, menerapkan sistem pewarnaan berbasis fermentasi daun indigo alami (Indigofera tinctoria). Dalam proses produksinya, pengrajin menghasilkan dua produk unggulan: Selendang Indigo (Produk A) dan Kain Panjang Klasik (Produk B).\n\nUntuk menjaga kestabilan mutu warna biru alami, ekstraksi pasta indigo dilakukan terpusat setiap pagi dengan kuota maksimal 150 liter larutan siap pakai per hari kerja. Di samping keterbatasan bahan pewarna, proses fiksasi warna membutuhkan ruang penganginan dan pencelupan terkontrol dengan total waktu operasional bersama maksimal 100 jam mesin per hari.\n\nBerdasarkan pencatatan siklus kerja bulanan:\n• Setiap helai Selendang Indigo (x) membutuhkan 3 liter larutan pewarna alami dan 2 jam proses mesin fiksasi warna.\n• Setiap helai Kain Panjang Klasik (y) membutuhkan 5 liter larutan pewarna alami dan 4 jam proses mesin fiksasi warna.\n\nDari sisi ekonomi, penjualan Selendang Indigo menghasilkan laba bersih Rp45.000 per helai, sedangkan Kain Panjang Klasik memberikan laba bersih Rp80.000 per helai. Mengingat tingginya permintaan menjelang pameran kriya nasional, koperasi pengrajin berencana merumuskan jadwal produksi harian yang memaksimalkan total laba tanpa melanggar batasan ketersediaan bahan larutan maupun kuota waktu mesin fiksasi.\n\nPengrajin juga menyepakati bahwa jumlah produksi kedua jenis kain tidak mungkin bernilai negatif (x ≥ 0 dan y ≥ 0), serta seluruh kain yang diproduksi terjamin langsung terserap oleh mitra galeri."}'::jsonb);
insert into public.media_assets (id, kind, storage_path, alt_text, transcript, pasteable) values
  ('d9ad9e1a-8f07-3d1a-bcf2-6f2324c9b59b', 'diagram', '1fe80267-0998-bf19-5658-92ac338d5430/media-parabola-01', 'Grafik fungsi kuadrat membuka ke atas pada bidang kartesius dengan titik puncak di (2, −1) dan memotong sumbu-X di x = 1 dan x = 3.', null, true);
insert into public.items (id, code, competency_id, tier, answer_type, stem, options, answer_key, equivalents, tolerance, distractor_hints, explanation, layout_mode, stimulus_id, difficulty, status, version) values
  ('837e61ae-1058-0237-8324-8e953877308d', 'MAT-SMA-ALJ-01', '3f6a9564-cc5c-e9c0-3e4d-d66627b223d6', 'mahir', 'pg', '{"text":"Diketahui fungsi kuadrat f(x) = 2x² − 4x + (k − 1). Jika grafik kurva parabola tersebut memotong sumbu-X di dua titik berlainan, tentukan batasan nilai k yang memenuhi persamaan tersebut!","formula":"D = b^2 - 4ac > 0 \\implies (-4)^2 - 4(2)(k - 1) > 0"}'::jsonb, '[{"id":"a","label":"A","text":"k < 3"},{"id":"b","label":"B","text":"k > 3"},{"id":"c","label":"C","text":"k < −3"},{"id":"d","label":"D","text":"k ≤ 3"},{"id":"e","label":"E","text":"k ≥ 3"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Perhatikan tanda pertidaksamaan: −8k > −24 menghasilkan k < 3, bukan k > 3.","c":"Periksa kembali pembagian dengan bilangan negatif: 24 − 8k > 0 berarti k < 3.","d":"Syarat grafik memotong sumbu-X di dua titik berbeda adalah D > 0, bukan D ≥ 0.","e":"Diskriminan harus bernilai positif agar ada dua akar real berlainan, dan itu terjadi saat k < 3."}'::jsonb, '{"text":"Agar memotong sumbu-X di dua titik berbeda, D > 0. D = (−4)² − 4(2)(k − 1) = 16 − 8k + 8 = 24 − 8k. Dari 24 − 8k > 0 diperoleh k < 3."}'::jsonb, 'standar', null, 0.45, 'published', 1),
  ('1fe80267-0998-bf19-5658-92ac338d5430', 'MAT-SMA-GEO-02', 'c05bb498-3d07-d157-83a9-82c155fc723d', 'mahir', 'pg', '{"text":"Perhatikan grafik fungsi kuadrat pada diagram kartesius di samping. Parabola tersebut memotong sumbu-X di titik (1, 0) dan (3, 0), serta mencapai titik puncak minimum pada koordinat (2, −1). Persamaan kurva parabola yang tepat adalah …","media_ids":["d9ad9e1a-8f07-3d1a-bcf2-6f2324c9b59b"]}'::jsonb, '[{"id":"a","label":"A","text":"f(x) = x² − 4x + 3"},{"id":"b","label":"B","text":"f(x) = x² − 4x − 3"},{"id":"c","label":"C","text":"f(x) = 2x² − 4x + 3"},{"id":"d","label":"D","text":"f(x) = x² + 4x + 3"},{"id":"e","label":"E","text":"f(x) = (x − 2)² + 1"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Grafik memotong sumbu-Y di (0, 3), jadi suku konstantanya +3, bukan −3.","c":"Substitusikan puncak (2, −1) ke a(x − 1)(x − 3): a(1)(−1) = −1, sehingga a = 1, bukan 2.","d":"Sumbu simetri berada di x = −b/(2a) = 2, sehingga koefisien b harus negatif (−4).","e":"Bentuk puncak dengan titik (2, −1) adalah f(x) = (x − 2)² − 1, bukan + 1."}'::jsonb, '{"text":"Parabola memotong sumbu-X di x = 1 dan x = 3, jadi f(x) = a(x − 1)(x − 3). Titik puncak (2, −1) memberi a(1)(−1) = −1, sehingga a = 1. Jadi f(x) = (x − 1)(x − 3) = x² − 4x + 3."}'::jsonb, 'media', null, 0.4, 'published', 1),
  ('77ddea7e-837a-8409-bb21-f59a1e351b26', 'MAT-SMA-LIT-03', 'f01cb809-7815-5a78-2b21-87c553e36bf0', 'ujian', 'pg', '{"text":"Berdasarkan stimulus bacaan di atas, jika x menyatakan jumlah Selendang Indigo dan y menyatakan jumlah Kain Panjang Klasik yang diproduksi setiap hari, tentukan model sistem pertidaksamaan linear yang membatasi ketersediaan bahan pewarna dan kuota waktu mesin fiksasi!"}'::jsonb, '[{"id":"a","label":"A","text":"3x + 5y ≤ 150; 2x + 4y ≤ 100; x ≥ 0; y ≥ 0"},{"id":"b","label":"B","text":"5x + 3y ≤ 150; 4x + 2y ≤ 100; x ≥ 0; y ≥ 0"},{"id":"c","label":"C","text":"3x + 5y ≥ 150; 2x + 4y ≥ 100; x ≥ 0; y ≥ 0"},{"id":"d","label":"D","text":"3x + 2y ≤ 100; 5x + 4y ≤ 150; x ≥ 0; y ≥ 0"},{"id":"e","label":"E","text":"3x + 5y ≤ 100; 2x + 4y ≤ 150; x ≥ 0; y ≥ 0"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Selendang (x) membutuhkan 3 liter pewarna dan 2 jam mesin; koefisien x dan y tertukar.","c":"Kuota pewarna dan waktu mesin adalah batas maksimal, jadi tandanya ≤, bukan ≥.","d":"Setiap pertidaksamaan memuat satu sumber daya: liter pewarna (3x + 5y) dan jam mesin (2x + 4y).","e":"Batas pewarna 150 liter dan waktu mesin 100 jam; ruas kanannya tertukar."}'::jsonb, '{"text":"Pewarna: 3 liter per selendang dan 5 liter per kain, maksimal 150 liter, sehingga 3x + 5y ≤ 150. Waktu mesin: 2 jam dan 4 jam, maksimal 100 jam, sehingga 2x + 4y ≤ 100. Jumlah produksi tidak negatif: x ≥ 0 dan y ≥ 0."}'::jsonb, 'bacaan', '4d767ab6-78bf-ed52-47ce-79b6647ab6f1', 0.55, 'published', 1),
  ('8989df82-2ebf-4ac2-bf19-b56c46aaa7be', 'MAT-SMA-ALJ-04', 'c05bb498-3d07-d157-83a9-82c155fc723d', 'mahir', 'pgk', '{"text":"Diberikan fungsi f(x) = x² − 2x + 5. Pilih semua pernyataan berikut yang benar mengenai karakteristik fungsi tersebut!","formula":"f(x) = (x - 1)^2 + 4"}'::jsonb, '[{"id":"a","label":"A","text":"Titik balik minimum berada di koordinat (1, 4)"},{"id":"b","label":"B","text":"Grafik memotong sumbu-Y di titik (0, −5)"},{"id":"c","label":"C","text":"Nilai minimum fungsi f(x) adalah 4"},{"id":"d","label":"D","text":"Kurva memotong sumbu-X di dua titik berlainan"}]'::jsonb, '["a","c"]'::jsonb, '[]'::jsonb, null, '{"b":"f(0) = 5, jadi grafik memotong sumbu-Y di (0, 5), bukan di (0, −5).","d":"Diskriminan D = (−2)² − 4(1)(5) = −16 < 0, sehingga kurva tidak memotong sumbu-X."}'::jsonb, '{"text":"f(x) = (x − 1)² + 4, jadi titik balik minimum (1, 4) dan nilai minimumnya 4. f(0) = 5, sehingga titik potong sumbu-Y adalah (0, 5). D = 4 − 20 = −16 < 0, jadi kurva tidak memotong sumbu-X."}'::jsonb, 'standar', null, 0.45, 'published', 1),
  ('3bba4c01-73f7-81d9-65ac-4666b2b4e251', 'MAT-SMA-MAT-05', '1d1ce9ca-b15a-5d27-e529-443645ded5e1', 'dasar', 'bs', '{"text":"Tentukan kebenaran dari masing-masing pernyataan terkait sifat dan operasi matriks persegi berikut ini!"}'::jsonb, '[{"id":"r1","label":"1","text":"Jika matriks A berordo 2×2 memiliki invers, maka determinan A ≠ 0."},{"id":"r2","label":"2","text":"Untuk setiap dua matriks persegi A dan B, selalu berlaku AB = BA."},{"id":"r3","label":"3","text":"Determinan matriks transpos det(Aᵀ) sama dengan det(A)."},{"id":"r4","label":"4","text":"Matriks singular adalah matriks yang memiliki nilai determinan bernilai satu."}]'::jsonb, '["r1","r3"]'::jsonb, '[]'::jsonb, null, '{"r2":"Perkalian matriks umumnya tidak komutatif; AB = BA hanya berlaku untuk pasangan matriks tertentu.","r4":"Matriks singular memiliki determinan sama dengan nol, bukan satu."}'::jsonb, '{"text":"Matriks punya invers jika dan hanya jika determinannya tidak nol (1 benar). Perkalian matriks umumnya tidak komutatif (2 salah). det(Aᵀ) = det(A) (3 benar). Matriks singular berdeterminan nol (4 salah)."}'::jsonb, 'standar', null, 0.3, 'published', 1),
  ('17cdf998-e2a1-73e2-b5b0-1ac2a6b16159', 'MAT-SMA-LIT-06', '9be7ad1f-28de-b912-42b7-30cd165d9af0', 'mahir', 'isian', '{"text":"Seorang pedagang membeli barang seharga Rp50.000 dan menjualnya kembali dengan keuntungan 20%. Berapakah harga jual barang tersebut (dalam rupiah)?"}'::jsonb, '[]'::jsonb, '["60000"]'::jsonb, '["60.000","60 ribu","Rp60.000","Rp 60.000","60000 rupiah"]'::jsonb, 0, '{}'::jsonb, '{"text":"Keuntungan 20% × Rp50.000 = Rp10.000, sehingga harga jual Rp50.000 + Rp10.000 = Rp60.000."}'::jsonb, 'standar', null, 0.25, 'published', 1),
  ('e40568ad-b311-b367-2d2f-6a59a80f454c', 'MAT-SMA-DIM-07', '65cb1d33-d4d3-573b-f232-74eb926300cd', 'ujian', 'pg', '{"text":"Diketahui kubus ABCD.EFGH dengan panjang rusuk 6 cm. Jarak dari titik C ke bidang diagonal BDHF adalah …","formula":"d = \\frac{1}{2} s \\sqrt{2}"}'::jsonb, '[{"id":"a","label":"A","text":"3 cm"},{"id":"b","label":"B","text":"3√2 cm"},{"id":"c","label":"C","text":"3√3 cm"},{"id":"d","label":"D","text":"6√2 cm"}]'::jsonb, '["b"]'::jsonb, '[]'::jsonb, null, '{"a":"Jarak titik ke bidang diukur sepanjang garis tegak lurus, yaitu dari C ke garis BD, bukan setengah rusuk.","c":"3√3 cm adalah setengah diagonal ruang; jarak C ke bidang BDHF sama dengan setengah diagonal sisi.","d":"6√2 cm adalah panjang diagonal sisi AC; jarak C ke bidang BDHF hanya setengahnya."}'::jsonb, '{"text":"Bidang BDHF memuat diagonal alas BD. Jarak C ke bidang itu sama dengan jarak C ke garis BD, yaitu setengah diagonal sisi: ½ × 6√2 = 3√2 cm."}'::jsonb, 'standar', null, 0.6, 'published', 1),
  ('66ee6f90-db07-3e49-7630-c5310e167c39', 'MAT-SMA-STA-08', '8a8f042e-1909-b3af-b6b5-72f09308b44f', 'ujian', 'pgk', '{"text":"Sekumpulan data memiliki rata-rata 50 dan simpangan baku 10. Jika setiap nilai data dikalikan 2 lalu dikurangi 5, pilih semua pernyataan yang benar!"}'::jsonb, '[{"id":"a","label":"A","text":"Rata-rata baru menjadi 100"},{"id":"b","label":"B","text":"Rata-rata baru menjadi 95"},{"id":"c","label":"C","text":"Simpangan baku baru menjadi 15"},{"id":"d","label":"D","text":"Simpangan baku baru menjadi 20"}]'::jsonb, '["b","d"]'::jsonb, '[]'::jsonb, null, '{"a":"Pengurangan 5 juga menggeser rata-rata: 2 × 50 − 5 = 95.","c":"Perkalian dengan 2 menggandakan simpangan baku menjadi 20; pengurangan 5 tidak mengubahnya."}'::jsonb, '{"text":"Rata-rata ikut setiap operasi: 2 × 50 − 5 = 95. Simpangan baku hanya terpengaruh perkalian: 2 × 10 = 20; pengurangan 5 menggeser semua data sama jauh sehingga sebarannya tetap."}'::jsonb, 'standar', null, 0.6, 'published', 1),
  ('336b4211-d3ff-a652-5e1a-edffb52fe8e9', 'MAT-SMA-BIL-09', '819a29ee-c2da-3ac1-cea5-d72b3341c7e6', 'dasar', 'isian', '{"text":"Tentukan nilai dari ²log 8 + ²log 4.","formula":"{}^{2}\\log 8 + {}^{2}\\log 4"}'::jsonb, '[]'::jsonb, '["5"]'::jsonb, '[]'::jsonb, 0, '{}'::jsonb, '{"text":"²log 8 = 3 karena 2³ = 8, dan ²log 4 = 2 karena 2² = 4. Jumlahnya 3 + 2 = 5."}'::jsonb, 'standar', null, 0.25, 'draft', 1),
  ('07158f0c-dafb-15d0-0ee8-1938f452c1d9', 'MAT-SMA-BIL-10', 'e79228dd-db23-1254-3d26-499a11151ab6', 'mahir', 'pg', '{"text":"Bentuk sederhana dari √50 − √18 + √8 adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"4√2"},{"id":"b","label":"B","text":"√40"},{"id":"c","label":"C","text":"10√2"},{"id":"d","label":"D","text":"0"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Bentuk akar tidak dijumlahkan dengan menjumlahkan bilangan di dalam akar; sederhanakan dulu menjadi kelipatan √2.","c":"√18 = 3√2 dikurangkan, bukan ditambahkan: 5√2 − 3√2 + 2√2.","d":"√8 = 2√2 ditambahkan, bukan dikurangkan: 5√2 − 3√2 + 2√2 = 4√2."}'::jsonb, '{"text":"√50 = 5√2, √18 = 3√2, dan √8 = 2√2. Jadi 5√2 − 3√2 + 2√2 = 4√2."}'::jsonb, 'standar', null, 0.4, 'draft', 1),
  ('ef66e919-0189-c6f9-089f-dc46bebdf7fc', 'MAT-SMA-ALJ-11', '7c538831-672a-cb59-780c-2c27fdf78b80', 'dasar', 'pg', '{"text":"Hasil pemfaktoran x² − 9 adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"(x − 3)(x + 3)"},{"id":"b","label":"B","text":"(x − 3)²"},{"id":"c","label":"C","text":"(x − 9)(x + 1)"},{"id":"d","label":"D","text":"(x + 3)²"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"(x − 3)² = x² − 6x + 9; ada suku −6x yang tidak muncul di soal.","c":"(x − 9)(x + 1) = x² − 8x − 9; ada suku −8x yang tidak muncul di soal.","d":"(x + 3)² = x² + 6x + 9; tandanya pun tidak sesuai."}'::jsonb, '{"text":"x² − 9 adalah selisih dua kuadrat: x² − 3² = (x − 3)(x + 3)."}'::jsonb, 'standar', null, 0.2, 'draft', 1),
  ('5d3250ff-6536-f1ce-d4ce-87cdd694158a', 'MAT-SMA-ARS-12', '9be7ad1f-28de-b912-42b7-30cd165d9af0', 'dasar', 'isian', '{"text":"Harga sebuah tas Rp240.000 mendapat diskon 25%. Berapa rupiah yang harus dibayar?"}'::jsonb, '[]'::jsonb, '["180000"]'::jsonb, '["180.000","Rp180.000","Rp 180.000"]'::jsonb, 0, '{}'::jsonb, '{"text":"Diskon 25% × Rp240.000 = Rp60.000, sehingga yang dibayar Rp240.000 − Rp60.000 = Rp180.000."}'::jsonb, 'standar', null, 0.25, 'draft', 1),
  ('b68f0742-6572-4044-993a-034e88763125', 'MAT-SMA-ALJ-13', '9d3126fc-8a77-e376-9778-269e6bce7cf3', 'dasar', 'isian', '{"text":"Tentukan nilai x yang memenuhi 5x − 7 = 2x + 8."}'::jsonb, '[]'::jsonb, '["5"]'::jsonb, '["x = 5"]'::jsonb, 0, '{}'::jsonb, '{"text":"Pindahkan suku x ke ruas kiri dan konstanta ke ruas kanan: 5x − 2x = 8 + 7, sehingga 3x = 15 dan x = 5."}'::jsonb, 'standar', null, 0.2, 'draft', 1),
  ('492f4706-46dc-dff7-1844-fe5dfaef00d3', 'MAT-SMA-ALJ-14', '795859b5-3db1-1646-e597-d12fa4a3f2c3', 'mahir', 'pg', '{"text":"Himpunan penyelesaian dari |x − 2| < 5 adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"−3 < x < 7"},{"id":"b","label":"B","text":"x < 7"},{"id":"c","label":"C","text":"−7 < x < 3"},{"id":"d","label":"D","text":"x < −3 atau x > 7"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Nilai mutlak memberi dua batas: selain x − 2 < 5, juga harus x − 2 > −5.","c":"Tambahkan 2 ke setiap ruas: −5 + 2 = −3 dan 5 + 2 = 7.","d":"Tanda < pada nilai mutlak menghasilkan selang di antara dua batas, bukan di luar."}'::jsonb, '{"text":"|x − 2| < 5 berarti −5 < x − 2 < 5. Tambahkan 2 ke setiap ruas: −3 < x < 7."}'::jsonb, 'standar', null, 0.45, 'draft', 1),
  ('ed6f2625-f940-a943-e1ff-dd28d9daa7b7', 'MAT-SMA-ALJ-15', 'ea0d7c9d-65c2-68f1-8736-47fb86c305c5', 'dasar', 'pg', '{"text":"Jika x + y = 10 dan x − y = 4, nilai x × y adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"21"},{"id":"b","label":"B","text":"40"},{"id":"c","label":"C","text":"7"},{"id":"d","label":"D","text":"14"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"40 adalah 10 × 4, hasil kali ruas kanan kedua persamaan, bukan x × y.","c":"7 adalah nilai x; soal menanyakan hasil kali x dan y.","d":"14 adalah 2x; bagi dulu dengan 2 untuk mendapatkan x = 7, lalu cari y."}'::jsonb, '{"text":"Jumlahkan kedua persamaan: 2x = 14, sehingga x = 7 dan y = 10 − 7 = 3. Jadi x × y = 21."}'::jsonb, 'standar', null, 0.25, 'draft', 1),
  ('03442280-044c-0d76-cdea-265890d15c72', 'MAT-SMA-MAT-16', '1d1ce9ca-b15a-5d27-e529-443645ded5e1', 'dasar', 'isian', '{"text":"Tentukan determinan matriks A berikut.","formula":"A = \\begin{pmatrix} 3 & 2 \\\\ 1 & 4 \\end{pmatrix}"}'::jsonb, '[]'::jsonb, '["10"]'::jsonb, '[]'::jsonb, 0, '{}'::jsonb, '{"text":"Untuk matriks 2×2, det(A) = ad − bc = 3 × 4 − 2 × 1 = 12 − 2 = 10."}'::jsonb, 'standar', null, 0.25, 'draft', 1),
  ('31623c34-eba6-fbf9-3033-4ac712142dec', 'MAT-SMA-MAT-17', '1d1ce9ca-b15a-5d27-e529-443645ded5e1', 'mahir', 'bs', '{"text":"Diberikan matriks A berikut. Tentukan benar atau salah setiap pernyataan.","formula":"A = \\begin{pmatrix} 2 & 1 \\\\ 0 & 3 \\end{pmatrix}"}'::jsonb, '[{"id":"r1","label":"1","text":"det(A) = 6"},{"id":"r2","label":"2","text":"Matriks A memiliki invers"},{"id":"r3","label":"3","text":"Aᵀ = A"},{"id":"r4","label":"4","text":"det(2A) = 12"}]'::jsonb, '["r1","r2"]'::jsonb, '[]'::jsonb, null, '{"r3":"Transpos menukar baris dan kolom: Aᵀ memiliki baris (2, 0) dan (1, 3), berbeda dari A.","r4":"Untuk matriks 2×2, det(kA) = k² det(A), sehingga det(2A) = 4 × 6 = 24."}'::jsonb, '{"text":"det(A) = 2 × 3 − 1 × 0 = 6 ≠ 0, sehingga A punya invers. Aᵀ berbeda dari A karena elemen di luar diagonal tertukar. det(2A) = 2² × 6 = 24."}'::jsonb, 'standar', null, 0.5, 'draft', 1),
  ('31405e83-22fd-da3c-20fc-14cfabf973cc', 'MAT-SMA-LIN-18', '001680ca-4152-96d4-f0d1-0b56f6184ec1', 'ujian', 'pg', '{"text":"Nilai maksimum f(x, y) = 3x + 2y pada daerah x + y ≤ 4, x ≥ 0, y ≥ 0 adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"12"},{"id":"b","label":"B","text":"8"},{"id":"c","label":"C","text":"20"},{"id":"d","label":"D","text":"4"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"8 adalah nilai di titik pojok (0, 4); periksa juga titik pojok (4, 0).","c":"Titik (4, 4) tidak memenuhi x + y ≤ 4, jadi bukan titik pojok daerah.","d":"4 adalah batas x + y, bukan nilai fungsi objektif."}'::jsonb, '{"text":"Titik pojok daerah: (0, 0), (4, 0), dan (0, 4). Nilai f: 0, 12, dan 8. Nilai maksimumnya 12 di (4, 0)."}'::jsonb, 'standar', null, 0.5, 'draft', 1),
  ('42fcdf5c-2b58-1cf2-07a2-893d7ded8b5e', 'MAT-SMA-FUN-19', '23a9a4ef-50cf-5409-ed84-f8df432d06cf', 'dasar', 'isian', '{"text":"Tentukan gradien garis yang melalui titik (2, 5) dan (6, 13)."}'::jsonb, '[]'::jsonb, '["2"]'::jsonb, '[]'::jsonb, 0, '{}'::jsonb, '{"text":"m = (y₂ − y₁) / (x₂ − x₁) = (13 − 5) / (6 − 2) = 8 / 4 = 2."}'::jsonb, 'standar', null, 0.25, 'draft', 1),
  ('5794edd4-aa42-cbc5-f652-fd192860755e', 'MAT-SMA-FUN-20', 'fa2e9c22-7f13-8e59-4fad-32a89151957a', 'mahir', 'pg', '{"text":"Jika f(x) = 2x + 1 dan g(x) = x², maka (f ∘ g)(3) adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"19"},{"id":"b","label":"B","text":"49"},{"id":"c","label":"C","text":"7"},{"id":"d","label":"D","text":"63"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"49 adalah (g ∘ f)(3) = g(7); pada f ∘ g, fungsi g dikerjakan lebih dulu.","c":"7 adalah f(3); hasil g(3) = 9 yang harus dimasukkan ke f.","d":"(f ∘ g)(3) adalah f(g(3)), bukan f(3) × g(3) = 7 × 9."}'::jsonb, '{"text":"(f ∘ g)(3) = f(g(3)). g(3) = 9, lalu f(9) = 2 × 9 + 1 = 19."}'::jsonb, 'standar', null, 0.4, 'draft', 1),
  ('d6c70c5a-8e94-8088-efc9-ec253312b6b5', 'MAT-SMA-FUN-21', 'fa2e9c22-7f13-8e59-4fad-32a89151957a', 'ujian', 'pg', '{"text":"Invers dari fungsi f(x) = (2x + 3) / 5 adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"f⁻¹(x) = (5x − 3) / 2"},{"id":"b","label":"B","text":"f⁻¹(x) = (5x + 3) / 2"},{"id":"c","label":"C","text":"f⁻¹(x) = (2x − 3) / 5"},{"id":"d","label":"D","text":"f⁻¹(x) = 5 / (2x + 3)"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Saat memindahkan 3 ke ruas lain, tandanya berubah: 5y − 3 = 2x.","c":"Invers diperoleh dengan menyelesaikan y = f(x) untuk x, bukan sekadar mengganti tanda.","d":"Invers fungsi tidak sama dengan kebalikan 1/f(x)."}'::jsonb, '{"text":"Tulis y = (2x + 3)/5, maka 5y = 2x + 3, sehingga x = (5y − 3)/2. Jadi f⁻¹(x) = (5x − 3)/2."}'::jsonb, 'standar', null, 0.55, 'draft', 1),
  ('b20188cc-af92-7284-ff21-3a9f5155b514', 'MAT-SMA-KUA-22', '2f41d7d5-9805-3055-f8d5-7def73be2e52', 'dasar', 'pg', '{"text":"Akar-akar persamaan x² − 5x + 6 = 0 adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"2 dan 3"},{"id":"b","label":"B","text":"−2 dan −3"},{"id":"c","label":"C","text":"1 dan 6"},{"id":"d","label":"D","text":"−1 dan 6"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Uji x = −2: 4 + 10 + 6 = 20, bukan 0. Faktornya (x − 2)(x − 3).","c":"1 + 6 = 7, padahal jumlah kedua akar harus 5.","d":"Hasil kali kedua akar harus 6 dan jumlahnya 5; −1 × 6 = −6."}'::jsonb, '{"text":"Cari dua bilangan yang jumlahnya 5 dan hasil kalinya 6, yaitu 2 dan 3: x² − 5x + 6 = (x − 2)(x − 3) = 0, sehingga x = 2 atau x = 3."}'::jsonb, 'standar', null, 0.2, 'draft', 1),
  ('63d8a3d6-142d-2d6d-9a0a-f3341510bd48', 'MAT-SMA-KUA-23', '3f6a9564-cc5c-e9c0-3e4d-d66627b223d6', 'mahir', 'pg', '{"text":"Persamaan x² + 4x + k = 0 mempunyai dua akar real kembar jika k = …"}'::jsonb, '[{"id":"a","label":"A","text":"4"},{"id":"b","label":"B","text":"−4"},{"id":"c","label":"C","text":"16"},{"id":"d","label":"D","text":"2"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Akar kembar berarti D = 0: 16 − 4k = 0, sehingga k bernilai positif.","c":"D = b² − 4ac = 16 − 4k; jangan lupa faktor 4 pada 4ac.","d":"Selesaikan 16 − 4k = 0 dengan membagi 16 oleh 4, bukan oleh 8."}'::jsonb, '{"text":"Akar kembar terjadi saat D = 0. D = 4² − 4(1)(k) = 16 − 4k = 0, sehingga k = 4."}'::jsonb, 'standar', null, 0.35, 'draft', 1),
  ('7637abf6-302e-e98a-cafb-7626cfdc7392', 'MAT-SMA-KUA-24', 'fd8ab079-b786-432c-ff05-b1d3a9909442', 'ujian', 'isian', '{"text":"Jika α dan β adalah akar-akar persamaan 2x² − 6x + 1 = 0, tentukan nilai α² + β²."}'::jsonb, '[]'::jsonb, '["8"]'::jsonb, '[]'::jsonb, 0, '{}'::jsonb, '{"text":"α + β = 6/2 = 3 dan αβ = 1/2. α² + β² = (α + β)² − 2αβ = 9 − 1 = 8."}'::jsonb, 'standar', null, 0.6, 'draft', 1),
  ('9a96e018-f186-08e2-bfec-761f8dc5aeea', 'MAT-SMA-KUA-25', '1d910c2d-602d-59aa-eb3f-7cc5c42afeff', 'ujian', 'pg', '{"text":"Persamaan kuadrat baru yang akar-akarnya dua kali akar-akar persamaan x² − 3x + 2 = 0 adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"x² − 6x + 8 = 0"},{"id":"b","label":"B","text":"x² − 3x + 4 = 0"},{"id":"c","label":"C","text":"2x² − 6x + 4 = 0"},{"id":"d","label":"D","text":"x² − 6x + 4 = 0"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Jika akar dikali 2, jumlah akar juga dikali 2 (menjadi 6) dan hasil kalinya dikali 4 (menjadi 8).","c":"Ini hanya mengalikan seluruh persamaan dengan 2; akarnya tetap 1 dan 2.","d":"Hasil kali akar baru adalah 2 × 4 = 8, bukan 4."}'::jsonb, '{"text":"Akar lama 1 dan 2, jadi akar baru 2 dan 4. Jumlahnya 6 dan hasil kalinya 8, sehingga persamaannya x² − 6x + 8 = 0."}'::jsonb, 'standar', null, 0.6, 'draft', 1),
  ('6783b06a-1b5e-e36a-286d-54f0409c1040', 'MAT-SMA-KUA-26', 'c05bb498-3d07-d157-83a9-82c155fc723d', 'mahir', 'pgk', '{"text":"Diberikan f(x) = −x² + 4x + 5. Pilih semua pernyataan yang benar!"}'::jsonb, '[{"id":"a","label":"A","text":"Grafiknya terbuka ke bawah"},{"id":"b","label":"B","text":"Sumbu simetrinya x = 2"},{"id":"c","label":"C","text":"Nilai maksimumnya 9"},{"id":"d","label":"D","text":"Grafiknya memotong sumbu-Y di (0, −5)"}]'::jsonb, '["a","b","c"]'::jsonb, '[]'::jsonb, null, '{"d":"f(0) = 5, jadi grafik memotong sumbu-Y di (0, 5)."}'::jsonb, '{"text":"Koefisien x² negatif, jadi grafik terbuka ke bawah. Sumbu simetri x = −4/(2 × (−1)) = 2, dan f(2) = −4 + 8 + 5 = 9 adalah nilai maksimum. f(0) = 5."}'::jsonb, 'standar', null, 0.5, 'draft', 1),
  ('26c6f584-2020-f2ac-4824-8c1850e27118', 'MAT-SMA-BAR-27', '8431313c-ce9c-8f88-cc6a-63eb0a4ece96', 'dasar', 'isian', '{"text":"Tentukan suku ke-10 dari barisan aritmetika 3, 7, 11, 15, …"}'::jsonb, '[]'::jsonb, '["39"]'::jsonb, '[]'::jsonb, 0, '{}'::jsonb, '{"text":"a = 3 dan b = 4, sehingga U₁₀ = a + 9b = 3 + 36 = 39."}'::jsonb, 'standar', null, 0.2, 'draft', 1),
  ('1e9058c4-0a02-a147-3cbc-f08e72479dc9', 'MAT-SMA-BAR-28', '8431313c-ce9c-8f88-cc6a-63eb0a4ece96', 'mahir', 'pg', '{"text":"Jumlah 20 suku pertama deret 2 + 5 + 8 + … adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"610"},{"id":"b","label":"B","text":"590"},{"id":"c","label":"C","text":"1.220"},{"id":"d","label":"D","text":"59"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Rumusnya Sₙ = n/2 (2a + (n − 1)b); suku pertama dikali 2.","c":"Jangan lupa membagi n dengan 2: Sₙ = n/2 (…).","d":"59 adalah suku ke-20 (2 + 19 × 3), bukan jumlahnya."}'::jsonb, '{"text":"a = 2, b = 3, n = 20. S₂₀ = 20/2 × (2 × 2 + 19 × 3) = 10 × 61 = 610."}'::jsonb, 'standar', null, 0.45, 'draft', 1),
  ('be92a750-47d8-581a-a0aa-933588d3c191', 'MAT-SMA-BAR-29', 'd55e2081-faa1-f0bb-7709-33486d445b2e', 'mahir', 'pg', '{"text":"Suku ke-6 dari barisan geometri 3, 6, 12, … adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"96"},{"id":"b","label":"B","text":"192"},{"id":"c","label":"C","text":"48"},{"id":"d","label":"D","text":"18"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Uₙ = a·rⁿ⁻¹; untuk n = 6 pangkatnya 5, bukan 6.","c":"48 adalah suku ke-5; hitung satu suku lagi.","d":"Barisan ini dikalikan 2 setiap suku, bukan ditambah 3."}'::jsonb, '{"text":"a = 3 dan r = 2, sehingga U₆ = 3 × 2⁵ = 3 × 32 = 96."}'::jsonb, 'standar', null, 0.35, 'draft', 1),
  ('4674ef98-7450-b7b2-3fb1-a57e9dcd193a', 'MAT-SMA-BAR-30', 'c0667636-929a-f11b-a134-a4aa08acf223', 'ujian', 'isian', '{"text":"Modal Rp1.000.000 disimpan dengan bunga majemuk 10% per tahun. Berapa rupiah nilainya setelah 2 tahun?"}'::jsonb, '[]'::jsonb, '["1210000"]'::jsonb, '["1.210.000","Rp1.210.000","Rp 1.210.000"]'::jsonb, 0, '{}'::jsonb, '{"text":"Nilai akhir = 1.000.000 × (1 + 0,1)² = 1.000.000 × 1,21 = Rp1.210.000."}'::jsonb, 'standar', null, 0.5, 'draft', 1),
  ('36af41a9-858e-3fec-4d6a-c52d676d5c39', 'MAT-SMA-GEO-31', 'b7180a58-3a67-72fd-35d1-00e3e7b77c83', 'dasar', 'isian', '{"text":"Sebuah segitiga siku-siku memiliki sisi tegak 6 cm dan 8 cm. Tentukan panjang sisi miringnya (dalam cm)."}'::jsonb, '[]'::jsonb, '["10"]'::jsonb, '["10 cm"]'::jsonb, 0, '{}'::jsonb, '{"text":"Dengan teorema Pythagoras: c² = 6² + 8² = 36 + 64 = 100, sehingga c = 10 cm."}'::jsonb, 'standar', null, 0.15, 'draft', 1),
  ('0b45d538-a1ae-0fa6-4d21-ae3dfb6262b9', 'MAT-SMA-TRI-32', 'dd8798bc-e549-1219-1ed2-d451daf04ae5', 'dasar', 'pg', '{"text":"Nilai sin 30° + cos 60° adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"1"},{"id":"b","label":"B","text":"½"},{"id":"c","label":"C","text":"√3"},{"id":"d","label":"D","text":"0"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"sin 30° dan cos 60° masing-masing bernilai ½; jumlahkan keduanya.","c":"√3/2 adalah nilai cos 30° dan sin 60°, bukan sin 30° dan cos 60°.","d":"sin 30° = cos 60° = ½, keduanya positif sehingga jumlahnya tidak nol."}'::jsonb, '{"text":"sin 30° = ½ dan cos 60° = ½, sehingga jumlahnya ½ + ½ = 1."}'::jsonb, 'standar', null, 0.2, 'draft', 1),
  ('b89dd11d-8b92-5231-7afa-ba54e5cc4eae', 'MAT-SMA-TRI-33', 'cab4a914-4f4a-6787-329b-eaacf07a024b', 'ujian', 'pg', '{"text":"Pada segitiga ABC, AB = 5 cm, AC = 8 cm, dan sudut A = 60°. Panjang BC adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"7 cm"},{"id":"b","label":"B","text":"√89 cm"},{"id":"c","label":"C","text":"√129 cm"},{"id":"d","label":"D","text":"13 cm"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Aturan kosinus: kurangi 2 × AB × AC × cos A dari 25 + 64.","c":"Suku 2 × AB × AC × cos A dikurangkan, bukan ditambahkan.","d":"Panjang sisi tidak diperoleh dengan menjumlahkan dua sisi lain; gunakan aturan kosinus."}'::jsonb, '{"text":"BC² = AB² + AC² − 2 × AB × AC × cos 60° = 25 + 64 − 2 × 5 × 8 × ½ = 89 − 40 = 49, sehingga BC = 7 cm."}'::jsonb, 'standar', null, 0.6, 'draft', 1),
  ('da686a17-f818-258e-bdd4-4ab5835883e3', 'MAT-SMA-DIM-34', '65cb1d33-d4d3-573b-f232-74eb926300cd', 'mahir', 'pg', '{"text":"Panjang diagonal ruang kubus dengan rusuk 4 cm adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"4√3 cm"},{"id":"b","label":"B","text":"4√2 cm"},{"id":"c","label":"C","text":"12 cm"},{"id":"d","label":"D","text":"8 cm"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"4√2 cm adalah diagonal sisi; diagonal ruang kubus adalah s√3.","c":"Diagonal ruang bukan jumlah tiga rusuk; gunakan s√3.","d":"Hitung √(4² + 4² + 4²) = √48 = 4√3, bukan 8."}'::jsonb, '{"text":"Diagonal ruang kubus = √(s² + s² + s²) = s√3 = 4√3 cm."}'::jsonb, 'standar', null, 0.35, 'draft', 1),
  ('390c6a91-0d96-a8d9-cf75-bedfb10707b9', 'MAT-SMA-STA-35', '9d92f4f4-0be7-db89-64b3-072fa792ccdb', 'mahir', 'bs', '{"text":"Diberikan data 2, 4, 6, 8, 10. Tentukan benar atau salah setiap pernyataan."}'::jsonb, '[{"id":"r1","label":"1","text":"Jangkauan data adalah 8"},{"id":"r2","label":"2","text":"Rata-rata data adalah 6"},{"id":"r3","label":"3","text":"Ragam (variansi) data adalah 8"},{"id":"r4","label":"4","text":"Simpangan baku data adalah 8"}]'::jsonb, '["r1","r2","r3"]'::jsonb, '[]'::jsonb, null, '{"r4":"Simpangan baku adalah akar dari ragam: √8 = 2√2, bukan 8."}'::jsonb, '{"text":"Jangkauan 10 − 2 = 8. Rata-rata 30/5 = 6. Ragam = (16 + 4 + 0 + 4 + 16)/5 = 8. Simpangan baku = √8 = 2√2."}'::jsonb, 'standar', null, 0.5, 'draft', 1),
  ('22009968-da51-b919-98b3-5c3589f79c85', 'MAT-SMA-STA-36', '8a8f042e-1909-b3af-b6b5-72f09308b44f', 'ujian', 'pg', '{"text":"Sekumpulan data memiliki median 20 dan jangkauan 12. Setiap nilai data dikalikan 3 lalu ditambah 4. Median dan jangkauan data baru berturut-turut adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"64 dan 36"},{"id":"b","label":"B","text":"64 dan 40"},{"id":"c","label":"C","text":"60 dan 36"},{"id":"d","label":"D","text":"24 dan 16"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Penambahan konstanta tidak mengubah jangkauan; hanya perkalian yang berpengaruh: 3 × 12 = 36.","c":"Median ikut bergeser karena penambahan: 3 × 20 + 4 = 64.","d":"Setiap nilai dikalikan 3 lebih dulu, bukan hanya ditambah 4."}'::jsonb, '{"text":"Median ikut kedua operasi: 3 × 20 + 4 = 64. Jangkauan hanya ikut perkalian: 3 × 12 = 36."}'::jsonb, 'standar', null, 0.55, 'draft', 1),
  ('e7426224-a01b-0eb9-d41c-2066929dfb86', 'MAT-SMA-PEL-37', 'e8a24adf-5b58-41b8-1504-8e35d3777f3c', 'mahir', 'pg', '{"text":"Banyak cara memilih 3 orang pengurus (tanpa jabatan) dari 7 calon adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"35"},{"id":"b","label":"B","text":"210"},{"id":"c","label":"C","text":"21"},{"id":"d","label":"D","text":"343"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"210 adalah permutasi (urutan diperhatikan); tanpa jabatan gunakan kombinasi.","c":"21 adalah C(7, 2); yang dipilih 3 orang, bukan 2.","d":"7³ menghitung pilihan dengan pengulangan; setiap orang hanya bisa dipilih sekali."}'::jsonb, '{"text":"Urutan tidak diperhatikan, jadi gunakan kombinasi: C(7, 3) = 7!/(3! × 4!) = 35."}'::jsonb, 'standar', null, 0.4, 'draft', 1),
  ('a397ed08-bf80-c36c-03b5-ac36fcaf0952', 'MAT-SMA-PEL-38', '644a76ac-ff48-0e1b-6245-d6d2aab6d6e1', 'ujian', 'pg', '{"text":"Dua dadu dilempar bersamaan. Peluang munculnya jumlah mata dadu 7 adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"1/6"},{"id":"b","label":"B","text":"7/36"},{"id":"c","label":"C","text":"1/12"},{"id":"d","label":"D","text":"1/2"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Ada 6 pasangan berjumlah 7: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1), bukan 7.","c":"Pasangan (1,6) dan (6,1) dihitung berbeda; ada 6 pasangan, bukan 3.","d":"Peluang = banyak kejadian ÷ 36 titik sampel; 6/36 jauh lebih kecil dari ½."}'::jsonb, '{"text":"Ruang sampel 6 × 6 = 36. Pasangan berjumlah 7 ada 6, sehingga peluangnya 6/36 = 1/6."}'::jsonb, 'standar', null, 0.45, 'draft', 1),
  ('b7055ab5-657e-c0ad-9716-a956154e356b', 'MAT-SMA-LOG-39', '20f24062-e798-5c43-df0e-fad664bdb25c', 'mahir', 'pg', '{"text":"Ingkaran dari pernyataan \"Semua siswa membawa tablet\" adalah …"}'::jsonb, '[{"id":"a","label":"A","text":"Ada siswa yang tidak membawa tablet"},{"id":"b","label":"B","text":"Semua siswa tidak membawa tablet"},{"id":"c","label":"C","text":"Tidak ada siswa yang membawa tablet"},{"id":"d","label":"D","text":"Ada siswa yang membawa tablet"}]'::jsonb, '["a"]'::jsonb, '[]'::jsonb, null, '{"b":"Ingkaran \"semua\" adalah \"ada … yang tidak\", bukan \"semua … tidak\".","c":"Pernyataan ini terlalu kuat; cukup satu siswa yang tidak membawa tablet.","d":"Pernyataan ini tidak bertentangan dengan pernyataan awal, jadi bukan ingkarannya."}'::jsonb, '{"text":"Ingkaran dari \"semua p\" adalah \"ada yang tidak p\". Jadi ingkarannya: ada siswa yang tidak membawa tablet."}'::jsonb, 'standar', null, 0.35, 'draft', 1),
  ('8d60c519-22d0-6f78-6460-45f34be2fb8e', 'MAT-SMA-POL-40', '8b9f45b3-2e0b-0038-a676-cec413710ef9', 'dasar', 'isian', '{"text":"Perhatikan pola bilangan 1, 4, 9, 16, … Tentukan suku ke-12."}'::jsonb, '[]'::jsonb, '["144"]'::jsonb, '[]'::jsonb, 0, '{}'::jsonb, '{"text":"Suku ke-n adalah n², sehingga suku ke-12 adalah 12² = 144."}'::jsonb, 'standar', null, 0.25, 'draft', 1);
